    import string
    alpha = string.ascii_letters + string.digits

    def make(n, mode, loops):
        names = set()
        while len(names) < n:
            names.add(''.join(rng.choice(alpha) for _ in range(rng.randint(1, 3 if n < 20 else 8))))
        names = list(names)
        rng.shuffle(names)
        lines = []
        roots = [names[0]]
        for i in range(1, n):
            if mode == 'chain':
                p = i - 1
            elif mode == 'star':
                p = 0
            elif mode == 'forest' and rng.random() < 0.2:
                roots.append(names[i])
                continue
            elif mode == 'deep':
                p = rng.randint(max(0, i - 3), i - 1)
            else:
                p = rng.randint(0, i - 1)
            lines.append(names[i] + '->' + names[p])
        if loops:
            for r in roots:
                if rng.random() < 0.6:
                    lines.append(r + '->' + r)
        if not lines:
            lines.append(names[0] + '->' + names[0])
        rng.shuffle(lines)
        return str(len(lines)) + '\n' + '\n'.join(lines)

    tests = ['1\nA->A', '1\nB->A', '2\nB->A\nA->A', '2\nB->A\nC->A', '3\nB->A\nC->B\nD->C',
